create or replace function private.combat_move_allowed(p_user uuid,p_channel text,p_move text,p private.player_progression_states,profile private.player_art_profiles) returns boolean language plpgsql stable security definer set search_path='' as $$declare required_level integer;v_sect_name text;begin if p_move='origin' then return p.spirit_path_opened;elsif p_move='body-origin' then return p.body_path_opened;elsif p_move like 'body-%' then required_level:=case p_move when 'body-jade-break' then 16 when 'body-mountain-crush' then 36 when 'body-myriad-calamity' then 56 when 'body-golden-boundary' then 68 when 'body-dao-incarnate' then 88 else null end;return required_level is not null and p.body_path_opened and p.body_level>=required_level;elsif p_move in('heavy-fall','heavy-rift','spirit-thread','spirit-return','shadow-stars','shadow-void') then return p.sword_path_opened and profile.sword_embryo=case when p_move like 'heavy-%' then 'heavy' when p_move like 'spirit-%' then 'spirit' else 'shadow' end and p.sword_trial_wins>=case when p_move in('heavy-rift','spirit-return','shadow-void') then 20 else 0 end;elsif p_move~'.+-2$' then v_sect_name:=regexp_replace(p_move,'-2$','');return exists(select 1 from private.player_sect_arts a where a.user_id=p_user and a.channel=p_channel and a.sect_name=v_sect_name and a.slot=2 and private.sect_slot_is_skill(a.sect_name,a.slot));end if;return false;end $$;
